set -eu
cat > /tmp/nftables.conf.ssh-rate-limit <<'ANTRIEB_NFT_EOF'
#!/usr/sbin/nft -f

flush ruleset

table inet filter {
    chain input {
        type filter hook input priority filter; policy accept;

        ct state established,related counter accept comment "Keep established administrative sessions available"

        meta nfproto ipv4 tcp dport 22 ct state new tcp flags & (fin | syn | rst | ack) == syn meter ssh_rate_v4 { ip saddr timeout 5m limit rate over 6/minute burst 10 packets } counter drop comment "Drop excessive new IPv4 SSH connections per source"
        meta nfproto ipv6 tcp dport 22 ct state new tcp flags & (fin | syn | rst | ack) == syn meter ssh_rate_v6 { ip6 saddr timeout 5m limit rate over 6/minute burst 10 packets } counter drop comment "Drop excessive new IPv6 SSH connections per source"

        tcp dport 22 ct state new tcp flags & (fin | syn | rst | ack) == syn counter accept comment "Allow normal new SSH connections"
    }

    chain forward {
        type filter hook forward priority filter; policy accept;
    }

    chain output {
        type filter hook output priority filter; policy accept;
    }
}
ANTRIEB_NFT_EOF
nft -c -f /tmp/nftables.conf.ssh-rate-limit
printf 'syntax_check=passed\n'
sed -n '1,220p' /tmp/nftables.conf.ssh-rate-limit

